<?php
require 'page-guard.php';require '../config/db_conn.php';require '../includes/teacher-profile-schema.php';ensureTeacherProfileColumns($conn);
$id=(int)($_POST['id']??0);$firstName=trim($_POST['first_name']??'');$lastName=trim($_POST['last_name']??'');$name=trim($firstName.' '.$lastName);$section=trim($_POST['section']??'');$subject=trim($_POST['subject']??'');$current=$_POST['current_password']??'';$pass=$_POST['teacher_pass']??'';$confirm=$_POST['teacher_confirm']??'';
if(!$id||$firstName===''||$lastName===''||$section===''||!in_array($subject,teacherSubjects(),true))exit('Invalid teacher details.');
$find=$conn->prepare('SELECT TEACHER_PASS FROM teachers WHERE TEACHER_ID=?');$find->bind_param('i',$id);$find->execute();$existing=$find->get_result()->fetch_assoc();
if($pass!==''||$current!==''){if(!$existing||!password_verify($current,$existing['TEACHER_PASS'])||strlen($pass)<8||$pass!==$confirm)exit('Current password is incorrect or the new passwords do not match.');$hash=password_hash($pass,PASSWORD_DEFAULT);$stmt=$conn->prepare('UPDATE teachers SET TEACHER_NAME=?,FIRST_NAME=?,LAST_NAME=?,SECTION=?,SUBJECT=?,TEACHER_PASS=? WHERE TEACHER_ID=?');$stmt->bind_param('ssssssi',$name,$firstName,$lastName,$section,$subject,$hash,$id);}else{$stmt=$conn->prepare('UPDATE teachers SET TEACHER_NAME=?,FIRST_NAME=?,LAST_NAME=?,SECTION=?,SUBJECT=? WHERE TEACHER_ID=?');$stmt->bind_param('sssssi',$name,$firstName,$lastName,$section,$subject,$id);}
$stmt->execute();$_SESSION['toast']=['message'=>'Teacher profile updated successfully.','type'=>'success'];header('Location: edit-teacher.php?id='.$id);exit;
